public class MainActivity extends Activity {
 LinearLayout page,body; JSONArray tasks=new JSONArray(); android.content.SharedPreferences prefs;
 String tab="車票",scene="黃昏",photoId; MediaPlayer music; AudioTrack rail; float railVolume=.35f;
 final int INK=0xff303632,GREEN=0xff405c4a,CREAM=0xfff5efdf;
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("journey",0);try{tasks=new JSONArray(prefs.getString("tasks","[]"));}catch(Exception e){toast("紀錄未能載入；請勿清除應用程式資料");}scene=prefs.getString("scene","黃昏");getWindow().setStatusBarColor(GREEN);getWindow().setNavigationBarColor(GREEN);render();String today=date(System.currentTimeMillis());if(!today.equals(prefs.getString("boarding","")))new AlertDialog.Builder(this).setTitle("今日乘車證 · "+today).setItems(new String[]{"輕鬆慢行","專心一程","休息充電"},(d,w)->{prefs.edit().putString("boarding",today).apply();toast("今日，由一小步開始。");}).setNegativeButton("直接上車",(d,w)->prefs.edit().putString("boarding",today).apply()).show();}
 String date(long t){return new SimpleDateFormat("yyyy-MM-dd",Locale.TRADITIONAL_CHINESE).format(new Date(t));}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
 void save(){prefs.edit().putString("tasks",tasks.toString()).apply();}
 TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(INK);v.setPadding(dp(5),dp(6),dp(5),dp(6));return v;}
 Button btn(String s,Runnable r){Button v=new Button(this);v.setText(s);v.setAllCaps(false);v.setTextColor(GREEN);v.setOnClickListener(x->r.run());return v;}
 void render(){page=new LinearLayout(this);page.setOrientation(1);page.setBackgroundColor(CREAM);page.setPadding(dp(14),0,dp(14),0);setContentView(page);page.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(14),i.getSystemWindowInsetTop(),dp(14),i.getSystemWindowInsetBottom());return i;});page.requestApplyInsets();page.addView(text("THE OVERLANDER / 漫遊日誌",19));page.addView(new Scenery(),new LinearLayout.LayoutParams(-1,dp(145)));page.addView(text("把做過的事，變成走過的路。",14));LinearLayout nav=new LinearLayout(this);for(String s:new String[]{"車票","日誌","收藏","聲音"})nav.addView(btn(s,()->{tab=s;render();}),new LinearLayout.LayoutParams(0,dp(48),1));page.addView(nav);ScrollView scroll=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);scroll.addView(body);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(tab.equals("車票"))tickets();if(tab.equals("日誌"))journal();if(tab.equals("收藏"))collection();if(tab.equals("聲音"))sounds();page.addView(text("本機儲存 · 測試版 · 尚未提供備份",11));}
 void tickets(){body.addView(btn("＋ 開一張車票",()->edit(null,false)));body.addView(btn("記低已經做過嘅事",()->edit(null,true)));int count=0;for(int j=0;j<tasks.length();j++){JSONObject o=tasks.optJSONObject(j);if(o!=null&&!o.optBoolean("done")){card(o);count++;}}if(count==0)body.addView(text("車票仲未寫好，下一站由你決定。",18));body.addView(btn("今日收車",()->{int n=0;for(int j=0;j<tasks.length();j++){JSONObject o=tasks.optJSONObject(j);if(o.optBoolean("done")&&date(o.optLong("completed")).equals(date(System.currentTimeMillis())))n++;}new AlertDialog.Builder(this).setTitle("收好今日").setMessage("今日留下 "+n+" 張票尾。\n未行完嘅路，可以下次再行。").setPositiveButton("翻開日誌",(d,w)->{tab="日誌";render();}).setNegativeButton("留喺車廂",null).show();}));}
 void edit(JSONObject existing,boolean done){LinearLayout f=new LinearLayout(this);f.setOrientation(1);f.setPadding(dp(20),0,dp(20),0);EditText title=new EditText(this);title.setHint("目的地 / 任務名稱");EditText note=new EditText(this);note.setHint("票背留一句（可留空）");if(existing!=null){title.setText(existing.optString("title"));note.setText(existing.optString("note"));}f.addView(title);f.addView(note);AlertDialog d=new AlertDialog.Builder(this).setTitle("寫一張車票").setView(f).setPositiveButton("收好",null).setNegativeButton("取消",null).create();d.setOnShowListener(x->d.getButton(-1).setOnClickListener(v->{if(title.getText().toString().trim().isEmpty()){title.setError("請寫低目的地");return;}try{JSONObject o=existing==null?new JSONObject():existing;o.put("title",title.getText().toString().trim());o.put("note",note.getText().toString());if(existing==null){o.put("id",UUID.randomUUID().toString());o.put("done",done);if(done)o.put("completed",System.currentTimeMillis());tasks.put(o);}save();d.dismiss();render();}catch(Exception e){toast("未能儲存，請重試");}}));d.show();}
 void card(JSONObject o){boolean done=o.optBoolean("done");LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(13),dp(9),dp(13),dp(9));GradientDrawable bg=new GradientDrawable();bg.setColor(0xfffffaeb);bg.setCornerRadius(dp(12));bg.setStroke(dp(1),0xffd8c6a8);c.setBackground(bg);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(8));body.addView(c,lp);c.addView(text(done?"已到站 · "+date(o.optLong("completed")):"自由車票 · 不限班次",12));TextView title=text(o.optString("title"),22);title.setTypeface(null,1);c.addView(title);if(!o.optString("note").isEmpty())c.addView(text(o.optString("note"),15));if(!o.optString("photo").isEmpty()){try{ImageView im=new ImageView(this);im.setImageURI(Uri.parse(o.optString("photo")));im.setAdjustViewBounds(true);im.setMaxHeight(dp(180));c.addView(im);}catch(Exception e){c.addView(text("相片暫時無法開啟",12));}}LinearLayout row=new LinearLayout(this);row.addView(btn(done?"復原完成":"驗票 · 完成",()->{try{o.put("done",!done);if(!done){o.put("completed",System.currentTimeMillis());cancelReminder(o);toast("已蓋日期印：呢一程，你行過喇。");}save();render();}catch(Exception e){toast("未能儲存");}}));row.addView(btn("票背 / 更多",()->menu(o)));c.addView(row);}
 void menu(JSONObject o){new AlertDialog.Builder(this).setTitle(o.optString("title")).setItems(new String[]{"修改 / 留一句","開始呢一程","加相片","提醒我","取消提醒","加入手機日曆","刪除車票"},(d,w)->{if(w==0)edit(o,false);if(w==1)new AlertDialog.Builder(this).setTitle("本程目的地").setMessage(o.optString("title")+"\n\n慢慢行，唔需要倒數。").setPositiveButton("繼續旅程",null).show();if(w==2){photoId=o.optString("id");Intent p=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE);p.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(p,8);}catch(ActivityNotFoundException e){toast("未找到相片選擇工具");}}if(w==3)remind(o);if(w==4){cancelReminder(o);toast("已取消提醒");}if(w==5){try{startActivity(new Intent(Intent.ACTION_INSERT).setData(CalendarContract.Events.CONTENT_URI).putExtra(CalendarContract.Events.TITLE,o.optString("title")).putExtra(CalendarContract.Events.DESCRIPTION,o.optString("note")));}catch(ActivityNotFoundException e){toast("未找到可新增行程嘅日曆 App");}}if(w==6)new AlertDialog.Builder(this).setMessage("刪除呢張車票？").setNegativeButton("取消",null).setPositiveButton("刪除",(dd,ww)->{cancelReminder(o);for(int j=tasks.length()-1;j>=0;j--)if(tasks.optJSONObject(j).optString("id").equals(o.optString("id")))tasks.remove(j);save();render();}).show();}).show();}
 Intent alarmIntent(JSONObject o){return new Intent(this,ReminderReceiver.class).setData(Uri.parse("overlander://reminder/"+o.optString("id"))).putExtra("id",o.optString("id"));}
 void cancelReminder(JSONObject o){PendingIntent p=PendingIntent.getBroadcast(this,0,alarmIntent(o),PendingIntent.FLAG_NO_CREATE|PendingIntent.FLAG_IMMUTABLE);if(p!=null){((AlarmManager)getSystemService(ALARM_SERVICE)).cancel(p);p.cancel();}((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(o.optString("id").hashCode());}
 void remind(JSONObject o){if(o.optBoolean("done")){toast("已完成嘅車票唔需要提醒");return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},12);toast("授權後請再選擇提醒時間");return;}new AlertDialog.Builder(this).setTitle("幾時提醒？（約略時間）").setItems(new String[]{"15 分鐘後","1 小時後","明日呢個時間"},(d,w)->{PendingIntent p=PendingIntent.getBroadcast(this,0,alarmIntent(o),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);try{((AlarmManager)getSystemService(ALARM_SERVICE)).setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+new long[]{900000,3600000,86400000}[w],p);toast("已安排約略提醒；重啟手機後需重新設定");}catch(Exception e){toast("提醒未能安排");}}).show();}
 void journal(){int n=0;for(int j=tasks.length()-1;j>=0;j--){JSONObject o=tasks.optJSONObject(j);if(o!=null&&o.optBoolean("done")){card(o);n++;}}if(n==0)body.addView(text("第一個足印，會由一件小事開始。",18));}
 void collection(){int n=0;for(int j=0;j<tasks.length();j++)if(tasks.optJSONObject(j).optBoolean("done"))n++;body.addView(text("旅程收藏 · 已完成 "+n+" 程",22));body.addView(text("虛構旅程站點，唔代表真實到訪紀錄。",12));String[] names={"山間小站","海邊月台","雨中小鎮","森林支線","夜行終點"};for(int j=0;j<names.length;j++){int goal=(j+1)*3;body.addView(text((n>=goal?"已收藏：":"未到達：")+names[j]+" · "+goal+" 程",19));}body.addView(text("冇連勝，冇扣分；復原完成會同步更新。",13));}
 void startRail(){try{if(rail==null){int rate=22050,len=rate*6;short[] pcm=new short[len];Random random=new Random(41);double low=0;for(int i=0;i<len;i++){double t=i/(double)rate;double noise=random.nextDouble()*2-1;low=.96*low+.04*noise;double q=t%.75;double envelope=Math.exp(-q*34)+(q>=.16? .65*Math.exp(-(q-.16)*34):0);double value=.18*low+.22*envelope*Math.sin(2*Math.PI*92*t)+.025*noise;double edge=Math.min(1,Math.min(t/.03,(6-t)/.03));pcm[i]=(short)(Math.tanh(value)*20000*edge);}rail=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(rate).setEncoding(AudioFormat.ENCODING_PCM_16BIT).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).build()).setBufferSizeInBytes(len*2).setTransferMode(AudioTrack.MODE_STATIC).build();rail.write(pcm,0,len);rail.setLoopPoints(0,len,-1);}rail.setVolume(railVolume);if(rail.getPlayState()==AudioTrack.PLAYSTATE_PLAYING)rail.pause();else rail.play();}catch(Exception e){toast("火車聲未能播放");if(rail!=null){rail.release();rail=null;}}}
 void sounds(){body.addView(text("窗邊收音機",24));body.addView(text("原創程序合成車輪聲 · 非實地錄音",13));body.addView(btn("播放 / 暫停火車聲",()->startRail()));SeekBar volume=new SeekBar(this);volume.setProgress((int)(railVolume*100));volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean user){railVolume=p/100f;if(rail!=null)rail.setVolume(railVolume);}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});body.addView(volume);body.addView(btn("選擇自己嘅音樂",()->{try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE),9);}catch(ActivityNotFoundException e){toast("未找到音樂選擇工具");}}));body.addView(btn("播放 / 暫停音樂",()->{if(music==null){toast("請先選擇音樂");return;}if(music.isPlaying())music.pause();else music.start();}));body.addView(text("離開 App 會暫停聲音；本版未有背景播放。",12));for(String s:new String[]{"晨光","黃昏","夜行"})body.addView(btn(s+"窗景",()->{scene=s;prefs.edit().putString("scene",s).apply();render();}));}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}if(request==8){try{for(int j=0;j<tasks.length();j++){JSONObject o=tasks.optJSONObject(j);if(o.optString("id").equals(photoId))o.put("photo",uri.toString());}save();render();}catch(Exception e){toast("相片未能加入");}}if(request==9){try{if(music!=null){music.release();music=null;}music=MediaPlayer.create(this,uri);if(music==null)throw new Exception();music.setLooping(true);music.start();}catch(Exception e){toast("未能播放呢個檔案");}}}
 protected void onPause(){super.onPause();if(rail!=null)rail.pause();if(music!=null&&music.isPlaying())music.pause();}
 protected void onDestroy(){if(rail!=null)rail.release();if(music!=null)music.release();super.onDestroy();}
 class Scenery extends View {Paint p=new Paint(3);Scenery(){super(MainActivity.this);}void rect(Canvas c,int col,float l,float t,float r,float b){p.setColor(col);c.drawRect(l,t,r,b,p);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();boolean night=scene.equals("夜行");rect(c,0xff795744,0,0,w,h);rect(c,night?0xff182b45:scene.equals("晨光")?0xffc3e0dc:0xffe9ba85,dp(8),dp(8),w-dp(8),h-dp(22));p.setColor(0xffffedb7);c.drawCircle(w*.77f,h*.26f,dp(17),p);Path hills=new Path();hills.moveTo(dp(8),h*.78f);hills.lineTo(w*.22f,h*.35f);hills.lineTo(w*.42f,h*.7f);hills.lineTo(w*.65f,h*.4f);hills.lineTo(w-dp(8),h*.78f);hills.lineTo(w-dp(8),h-dp(22));hills.lineTo(dp(8),h-dp(22));hills.close();p.setColor(night?0xff263d42:0xff64836b);c.drawPath(hills,p);rect(c,0xff425d49,dp(8),h*.8f,w-dp(8),h-dp(22));p.setColor(CREAM);p.setTextSize(dp(12));c.drawText(scene+"慢車 / THE OVERLANDER",dp(14),h-dp(6),p);}}
}
